import style from "./select-box.stories.module.less";
import { Meta, StoryObj } from "@storybook/react";
import SelectBox from "./select-box";
import { action } from "storybook/actions";
import { fn } from "storybook/test";
import { withBlockWrapper } from "../../../../.storybook/preview";
import { useState } from "react";

const meta = {
  title: "Primitives/Select Box",
  component: SelectBox,
  decorators: [withBlockWrapper],
  render: function StoryComponent(args) {
    const [selectedValue, setSelectedValue] = useState(args.value);

    return (
      <div className={style.wrapper}>
        <SelectBox
          {...args}
          value={selectedValue}
          onChange={(name, value) => {
            args.onChange?.(name, `Chosen option: ${value}`);
            setSelectedValue(value);
          }}
        />
      </div>
    );
  },
} satisfies Meta<typeof SelectBox>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Primary: Story = {
  args: {
    description: "Här kan man välja mellan olika alternativ",
    options: [
      { value: "1", label: "Alternativ 1" },
      { value: "2", label: "Alternativ 2" },
    ],
    notSelectedText: "Välj ett alternativ",
    name: "select",
    onChange: action("onChange"),
    onOpen: fn(),
  },
};

export const ManyOptions: Story = {
  args: {
    ...Primary.args,
    shouldShowCheckIcon: false,
    description: "Många olika alternativ. Minska fönsterstorleken för att se scrollning.",
    options: Array.from({ length: 20 }, (_, i) => ({ value: `${i}`, label: `Alternativ ${i}` })),
  },
};

export const WithFormFieldProps: Story = {
  args: {
    ...Primary.args,
    name: "select",
    isRequired: true,
    isValid: true,
    errorText: "Detta fält är obligatoriskt",
    options: [
      { value: "1", label: "Formfield Alternativ 1" },
      { value: "2", label: "Formfield Alternativ 2" },
    ],
    helperText: "Här kan man skriva lite hjälptext",
    description: "Välj ett alternativ (från formField)",
  },
};
